// golive_post_settings(), and changed_at stays (a discussion change isn't an edit, so it
// fires no post.saved plugin event and doesn't reorder "recently edited").
func (q *Queries) UpdatePostDiscussion(ctx context.Context, arg UpdatePostDiscussionParams) (Post, error) {
	row := q.db.QueryRowContext(ctx, updatePostDiscussion, arg.Discussion, arg.ID)
	var i Post
	err := row.Scan(
		&i.ID,
		&i.Title,
		&i.Description,
		&i.UserID,
		&i.Username,
		&i.Url,
		&i.PostType,
		&i.PostStatus,
		&i.PostParent,
		&i.MenuOrder,
		&i.CreatedAt,
		&i.ChangedAt,
		&i.BlockDoc,
		&i.BlockRevision,
		&i.PublishedVersionID,
		&i.PublishedBlockDoc,
		&i.Slug,
		&i.PublishedSettings,
		&i.BlockDocHash,
		&i.SeoTitle,
		&i.SeoDescription,
		&i.SocialImageID,
		&i.Noindex,
		&i.CanonicalUrl,
		&i.PublishAt,
		&i.PublishScheduledBy,
		&i.PublishAttempts,
		&i.PublishNextAttemptAt,
		&i.PublishFailedAt,
		&i.PublishError,
		&i.DeletedAt,
		&i.TrashedFromStatus,
		&i.PageTemplate,
		&i.PublishedBlockHash,
		&i.Discussion,
		&i.FirstPublishedAt,
	)
	return i, err
}

const upsertCommenter = `-- name: UpsertCommenter :one
INSERT INTO commenters (email, email_lower, display_name)
VALUES ($1, $2, $3)
ON CONFLICT (email_lower) DO UPDATE
SET email = EXCLUDED.email,
    display_name = EXCLUDED.display_name,
    last_seen_at = now()
RETURNING id, email, email_lower, display_name, verified_at, blocked_at, last_spam_at, user_id, created_at, last_seen_at
`

type UpsertCommenterParams struct {
	Email       string `json:"email"`
	EmailLower  string `json:"email_lower"`
	DisplayName string `json:"display_name"`
}

// One row per address (3.2): matched on email_lower; the latest name and address as
// typed win, and last_seen_at moves (which keeps the maintenance job off it).
func (q *Queries) UpsertCommenter(ctx context.Context, arg UpsertCommenterParams) (Commenter, error) {
	row := q.db.QueryRowContext(ctx, upsertCommenter, arg.Email, arg.EmailLower, arg.DisplayName)
	var i Commenter
	err := row.Scan(
		&i.ID,
		&i.Email,
		&i.EmailLower,
		&i.DisplayName,
		&i.VerifiedAt,
		&i.BlockedAt,
		&i.LastSpamAt,
		&i.UserID,
		&i.CreatedAt,
		&i.LastSeenAt,
	)
	return i, err
}
